new = '''import importlib                                 # noqa: E402
from nemo_automodel.cli.utils import load_yaml, resolve_recipe_name  # noqa: E402


def resolve_dotted(t):
    """Import a.b.c.D.method: the module/attribute boundary is not the last dot."""
    parts = t.split(".")
    for i in range(len(parts), 0, -1):
        try:
            obj = importlib.import_module(".".join(parts[:i]))
        except Exception:
            continue
        for a in parts[i:]:
            obj = getattr(obj, a)
        return obj
    raise ImportError(t)


cfg = load_yaml(YAML_PATH)
log("recipe ->", resolve_recipe_name(cfg["recipe"]))
