        except Exception as e:
            die("%s.%s = %s does not resolve: %r" % (sec, key, t, e))
        log("  OK %-22s %s" % (sec + "." + key.strip("_"), t))
    be = node.get("backend") if hasattr(node, "get") else None
    if isinstance(be, dict) and be.get("_target_"):
