    pc=d.get('per_case') or {}
    scores=[pc[k] for k in sorted(pc)]
    m=means_for(scores)
    code=(m[250],m[9750]); ceil=(m[249],m[9749]); npi=(qi(m,0.025),qi(m,0.975))
    same = (code==ceil) and abs(code[0]-npi[0])<1e-12 and abs(code[1]-npi[1])<1e-12
    print('%-40s stored=[%.4f,%.4f] code=[%.4f,%.4f] ceil=[%.4f,%.4f] interp=[%.6f,%.6f] identical=%s'%(
        f, d['ci95']['lo'], d['ci95']['hi'], code[0],code[1], ceil[0],ceil[1], npi[0],npi[1], same))

