def fold(treat_lit_as_kept):
    passing={}; counts={}
    for d in draws:
        cid=d['case_id']; c=counts.setdefault(cid,[0,0]); c[1]+=1
        kept = d.get('kept') or (treat_lit_as_kept and d.get('reason')=='literal-output')
        if kept:
            c[0]+=1; passing.setdefault(cid,[]).append(d)
    rows=0
    for cid,ds in passing.items():
        best=sorted({d['program'] for d in ds}, key=lambda p:(len(p),p))[:2]
        rows+=len(best)
    solved=[c for c,(p,_) in counts.items() if p>0]
    return len(counts), len(solved), rows
print("as-shipped:", fold(False))
print("if literal guard removed:", fold(True))

