import sys,random; sys.path.insert(0,'.')
from pipeline import stats
from pipeline.jsonio import read_jsonl
def per_case(r):
    ag={}
    for a in read_jsonl('runs/%s/attempts.jsonl'%r):
        if a.get('harness_error'): continue
        ag.setdefault(a['case_id'],[]).append(1.0 if a.get('passed') else 0.0)
    return {k:sum(v)/len(v) for k,v in ag.items()}
P=list(per_case('headroom-k16').values()); n=74
def corr(a,b):
    ma,mb=sum(a)/len(a),sum(b)/len(b)
    num=sum((u-ma)*(v-mb) for u,v in zip(a,b))
    den=(sum((u-ma)**2 for u in a)*sum((v-mb)**2 for v in b))**.5
    return num/den if den else 0.0
def draw(rng,m):
    idx=[rng.randrange(len(P)) for _ in range(n)]
    a=[P[i] for i in idx]
    b=[a[j] if rng.random()<m else P[rng.randrange(len(P))] for j in range(n)]
    base=[1.0 if rng.random()<p else 0.0 for p in a]
    cand=[1.0 if rng.random()<p else 0.0 for p in b]
    return base,cand
# calibrate m -> observed score correlation
for m in (0.0,0.3,0.5,0.7,0.85,1.0):
    rng=random.Random(3); cs=[]
    for _ in range(400):
        b,c=draw(rng,m); cs.append(corr(b,c))
    print('m=%.2f  induced score-rho=%.3f'%(m,sum(cs)/len(cs)))
print()
for m in (0.0,0.5,0.7,0.85,1.0):
    rng=random.Random(11); win=0; T=3000
    for _ in range(T):
        b,c=draw(rng,m)
        s=stats.summarize(c,resamples=2000,seed=rng.randrange(1<<30))
        if float(s['ci95']['lo'])>sum(b)/n: win+=1
    print('m=%.2f -> false WIN %.2f%%'%(m,100*win/T))

