"""Canonical JSON, stable ids, and JSONL that round-trips byte-for-byte.

Everything downstream hashes records, so there is exactly one serialization:
sorted keys, no spaces, UTF-8 kept as UTF-8. A record written twice is the same
bytes twice, which is what makes a frozen split checkable rather than promised.
"""

from __future__ import annotations

import hashlib
import json
import os
import tempfile
from pathlib import Path
from typing import Any, Dict, Iterable, Iterator, List


def canon(obj: Any) -> str:
    """The one serialization. Sorted, compact, unescaped."""
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def digest(obj: Any, length: int = 12) -> str:
    """A stable short hash of ``obj``'s canonical form."""
    return hashlib.sha256(canon(obj).encode("utf-8")).hexdigest()[:length]


def sha256_of(obj: Any) -> str:
    return hashlib.sha256(canon(obj).encode("utf-8")).hexdigest()


def read_jsonl(path: str | os.PathLike) -> List[Dict[str, Any]]:
    p = Path(path)
    if not p.exists():
        return []
    out: List[Dict[str, Any]] = []
    with p.open("r", encoding="utf-8") as fh:
        for n, line in enumerate(fh, 1):
            line = line.strip()
            if not line:
                continue
            try:
                out.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError("%s:%d: %s" % (p, n, exc)) from None
    return out


def iter_jsonl(path: str | os.PathLike) -> Iterator[Dict[str, Any]]:
    p = Path(path)
    if not p.exists():
        return
    with p.open("r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                yield json.loads(line)


def write_jsonl(path: str | os.PathLike, rows: Iterable[Dict[str, Any]]) -> int:
    """Write atomically. A half-written corpus is worse than no corpus."""
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    n = 0
    fd, tmp = tempfile.mkstemp(dir=str(p.parent), suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            for row in rows:
                fh.write(canon(row))
                fh.write("\n")
                n += 1
        os.replace(tmp, str(p))
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise
    return n


def append_jsonl(path: str | os.PathLike, row: Dict[str, Any]) -> None:
    """Append one record and fsync. The sweep must survive a preemption."""
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("a", encoding="utf-8") as fh:
        fh.write(canon(row))
        fh.write("\n")
        fh.flush()
        os.fsync(fh.fileno())


def write_json(path: str | os.PathLike, obj: Any) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=str(p.parent), suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(obj, fh, sort_keys=True, indent=2, ensure_ascii=False)
            fh.write("\n")
        os.replace(tmp, str(p))
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise


def read_json(path: str | os.PathLike) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))

import re, pathlib
p = pathlib.Path("src/lypning/assets/rust/src/methods.rs")
s = p.read_text()

# 1. FLOAT_MISSING / INT_MISSING shrink, and the two served tables appear next to them.
old_float = '''const FLOAT_MISSING: &[&str] = &[
    "as_integer_ratio", "conjugate", "from_number", "fromhex", "hex", "imag", "is_integer", "real",
];'''
new_float = '''const FLOAT_MISSING: &[&str] = &["conjugate", "from_number", "fromhex", "hex", "imag", "real"];

/// The two `float` methods this engine answers.
///
/// Both are EXACT and neither touches libm: `is_integer` is a comparison, and
/// `as_integer_ratio` reads the mantissa and exponent out of the bits. That is
/// the whole reason these two are here and `hex`/`fromhex` are not — a method
/// whose answer is a rounded double is a MISMATCH waiting for the right input,
/// and one whose answer is an integer pair is not.
const FLOAT_METHODS: &[&str] = &["as_integer_ratio", "is_integer"];'''
assert old_float in s
s = s.replace(old_float, new_float)

old_int = '''const INT_MISSING: &[&str] = &[
    "as_integer_ratio", "bit_count", "bit_length", "conjugate", "denominator", "from_bytes",
    "imag", "is_integer", "numerator", "real", "to_bytes",
];'''
new_int = '''const INT_MISSING: &[&str] = &[
    "as_integer_ratio", "bit_count", "conjugate", "denominator", "imag", "is_integer", "numerator",
    "real",
];

/// The three `int` methods this engine answers — a bit count and the two
/// base-256 conversions, all three exact and none of them libm.
///
/// **The names left in [`INT_MISSING`] are left there on purpose, and the rule
/// is the same one `FLOAT_MISSING`'s note states about `from_number`: a method
/// CPython GREW is a MISMATCH on an older reference interpreter.**
/// `int.bit_count()` is 3.10 and `int.is_integer()` is 3.12, so serving either
/// would answer where a 3.9 CPython raises `AttributeError` — and this engine
/// is graded against whatever interpreter the caller has, not against the
/// newest one. The same rule governs the DEFAULTS of the two conversions
/// below, which are 3.11's and are refused rather than served.
const INT_METHODS: &[&str] = &["bit_length", "from_bytes", "to_bytes"];'''
assert old_int in s
s = s.replace(old_int, new_int)

# 2. method_name gains the two numeric rows.
old = '''        Value::Bytes(_) => BYTES_METHODS,
        Value::Tuple(_) => TUPLE_METHODS,
        Value::File(_) => FILE_METHODS,
        _ => return None,
    };
    find_sorted(table, name)'''
new = '''        Value::Bytes(_) => BYTES_METHODS,
        Value::Tuple(_) => TUPLE_METHODS,
        Value::File(_) => FILE_METHODS,
        // `bool` is a subclass of `int` and reads `int`'s table: `True.to_bytes(1,
        // 'big')` is `b'\\x01'` in CPython. The one place the subclass shows
        // through is `from_bytes`, a CLASSMETHOD whose result is `cls` — so
        // `bool.from_bytes(b'\\x02', 'big')` is `True` and not `2`, and
        // [`int_method`] refuses that receiver rather than answer an int for it.
        Value::Int(_) | Value::Bool(_) => INT_METHODS,
        Value::Float(_) => FLOAT_METHODS,
        _ => return None,
    };
    find_sorted(table, name)'''
assert old in s
s = s.replace(old, new)

# 3. accepts_kw: the two conversions take `signed=`.
old = '''        "list" => name == "sort",
        "dict" => name == "update",
        _ => false,'''
new = '''        "list" => name == "sort",
        "dict" => name == "update",
        // `signed=` is KEYWORD-ONLY on both, and CPython takes `length=` and
        // `byteorder=` by name as well — `int_method` refuses those two rather
        // than raise the TypeError this predicate would otherwise produce.
        "int" => matches!(name, "from_bytes" | "to_bytes"),
        _ => false,'''
assert old in s
s = s.replace(old, new)

# 4. call_method: the classmethod, and the two numeric receivers.
old = '''    if let Value::Builtin(t) = recv {
        let mut args = args;
        if args.is_empty() {'''
new = '''    if let Value::Builtin(t) = recv {
        // `int.from_bytes(b, 'big')` is a CLASSMETHOD: the TYPE is the
        // receiver, so the first argument is the bytes and must not be shifted
        // off as one. Reached only through `get_attr`'s `int`/`bool` probe,
        // which is the same table read off the type object.
        if name == "from_bytes" && matches!(*t, "int" | "bool") {
            return int_method(recv, name, args, &kw);
        }
        let mut args = args;
        if args.is_empty() {'''
assert old in s
s = s.replace(old, new)

old = '''        Value::Tuple(t) => tuple_method(t, name, args),
        Value::File(f) => file_method(it, f, name, args, kw),'''
new = '''        Value::Tuple(t) => tuple_method(t, name, args),
        Value::Int(_) | Value::Bool(_) => int_method(recv, name, args, &kw),
        Value::Float(f) => float_method(*f, name, args, &kw),
        Value::File(f) => file_method(it, f, name, args, kw),'''
assert old in s
s = s.replace(old, new)

p.write_text(s)
print("ok")

