OUT="/tmp/claude-0/-home-user-lypning/05e2ce2d-c800-5df6-a220-b3efcfe06b17/scratchpad/hunt"
rnd=random.Random(99)
def d(u): return struct.unpack('<d',struct.pack('<Q',u))[0]
def b(x): return struct.unpack('<Q',struct.pack('<d',x))[0]
vals=[]
while len(vals) < 300000:
    v=d(rnd.getrandbits(64))
    if math.isfinite(v):
        vals.append(v)
for e in range(-1074,1024):
    v=math.ldexp(1.0,e)
    if math.isfinite(v):
        vals.append(v)
        for k in (-2,-1,1,2):
            w=d((b(v)+k)&0xFFFFFFFFFFFFFFFF)
            if math.isfinite(w): vals.append(w)
for i in range(1,20001):
    vals.append(float(i)); vals.append(1.0/i); vals.append(i/7.0); vals.append(i*1e-7)
n=0
CH=60000
for i in range(0,len(vals),CH):
    f=open("%s/r%03d.py"%(OUT,n),"w")
    f.write("vs = [\n")
    for v in vals[i:i+CH]:
        f.write("%r,\n"%v)
    f.write("]\nfor v in vs:\n    print(repr(v))\n")
    f.close()
    n+=1
sys.stderr.write("vals %d chunks %d\n"%(len(vals),n))

