# 1. one home for the alias
p = Path("builtins.rs"); s = p.read_text()
anchor = "pub fn exception_static(n: &str) -> &'static str {"
helper = '''/// The name CPython would give the class `n` — its `__qualname__`, and its
/// IDENTITY.
///
/// `IOError is EnvironmentError is OSError`: one class under three names, so
/// all three are one object and all three answer `OSError`. Everything else
/// answers itself. Two readers — `ops::get_attr`'s `__name__` and
/// `value::is_same` — because a name that decides what `__name__` prints and a
/// name that decides what `is` answers are the same name, and having them agree
/// by coincidence is how `IOError.__name__` came to say `IOError` while
/// `repr(IOError)` said `<class 'OSError'>` one line away.
pub fn canonical_class(n: &str) -> &str {
    match n {
        "IOError" | "EnvironmentError" => "OSError",
        other => other,
    }
}

'''
assert anchor in s
p.write_text(s.replace(anchor, helper + anchor, 1))

# 2. __name__ reads it
p = Path("ops.rs"); s = p.read_text()
old = '''                let spelled = match *b {
                    "IOError" | "EnvironmentError" => "OSError",
                    other => other,
                };
                return Ok(Value::Str(spelled.into()));'''
new = '''                return Ok(Value::Str(crate::builtins::canonical_class(b).into()));'''
assert old in s
p.write_text(s.replace(old, new, 1))

# 3. `is` reads it too
p = Path("value.rs"); s = p.read_text()
old = '''        (Value::Builtin(x), Value::Builtin(y)) => x == y,'''
new = '''        // Through `canonical_class`, not by name: `IOError is OSError` is True
        // in CPython because they are ONE class, and comparing the spellings
        // answered False. A builtin FUNCTION is its own name and is unaffected
        // — the map has three entries and all three are classes.
        (Value::Builtin(x), Value::Builtin(y)) => {
            crate::builtins::canonical_class(x) == crate::builtins::canonical_class(y)
        }'''
assert old in s
p.write_text(s.replace(old, new, 1)); print("patched 3 files")

