ENV={'PATH':'/usr/local/bin:/usr/bin:/bin','LC_ALL':'C.UTF-8','LANG':'C.UTF-8'}

def run(engine, prog, argv, cwd):
    cmd=['/usr/bin/setpriv','--reuid=65534','--regid=65534','--clear-groups',
         os.path.join(BIN,engine),'-c',prog]+list(argv)
    env=dict(ENV); env['HOME']=cwd
    try:
        p=subprocess.run(cmd, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired:
        return -99, b'', b'TIMEOUT'

def one(k):
    o=rows[k]; prog=o['program']; argv=[str(a) for a in o.get('argv_tail') or []]
    d=tempfile.mkdtemp(prefix='s', dir=SBOX); os.chmod(d,0o777)
    try:
        rc,so,se=run('lypning',prog,argv,d)
        rec={'key':k,'rc0':rc,'se0':se.decode('utf8','replace')[:300],'so0_len':len(so)}
