def corr(x,y):
    ks=sorted(set(x)&set(y)); a=[x[k] for k in ks]; b=[y[k] for k in ks]
    ma,mb=sum(a)/len(a),sum(b)/len(b)
    num=sum((u-ma)*(v-mb) for u,v in zip(a,b))
