from __future__ import annotations
import json, os, shutil, subprocess, tempfile, collections
from pathlib import Path
SB = Path("/tmp/claude-0/-home-user-lypning/05e2ce2d-c800-5df6-a220-b3efcfe06b17/scratchpad/sb")
CPY="/usr/bin/python3"
def materialise(cwd, files):
    for name, content in (files or {}).items():
        p=cwd/name; p.parent.mkdir(parents=True,exist_ok=True)
        p.write_bytes(content.encode("latin-1") if any(ord(c)>127 for c in content) else content.encode("utf-8"))
def run(prog, rec):
    argv=[CPY,"-c",prog]+[str(a) for a in (rec.get("argv") or [])]
    env={"PATH":"/usr/bin:/bin","HOME":os.environ.get("HOME","/root"),"LC_ALL":"C.UTF-8"}
    cwd=Path(tempfile.mkdtemp(prefix="det-",dir=str(SB/"tmp")))
    try:
        materialise(cwd, rec.get("files"))
        p=subprocess.run(argv,input=(rec.get("stdin") or "").encode(),cwd=str(cwd),env=env,
                         stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=20)
        return p.returncode, p.stdout.decode("utf-8","replace")
    finally:
        shutil.rmtree(cwd, ignore_errors=True)
recs=[json.loads(l) for l in open(SB/"pairs.jsonl")]
bad=[]
for rec in recs:
    outs={run(rec["program"],rec) for _ in range(5)}
    if len(outs)!=1 or list(outs)[0][1]!=rec["expect_stdout"]:
        bad.append((rec["pair_id"],rec["task_id"],len(outs)))
print("pairs",len(recs),"non-deterministic-or-wrong over 5 more runs:",len(bad),bad[:10])

