# --------------------------------------------------------- reciting the answer
#
# "Reciting" is carrying the answer as data; "computing" is deriving it. The two
# are told apart by constant-folding only the operations that *re-encode* a value
# — concatenation, chr/ord, slicing, joining, decoding — and never arithmetic,
# because arithmetic on literals is what an honest rewrite of `6*7` looks like.

_FOLD_LIMIT = 8192
_REPEAT_LIMIT = 4096


class _NoFold(Exception):
    """This expression is not a re-encoding of constants."""


_TRANSCRIBERS = {
    "chr": chr, "ord": ord, "str": str, "repr": repr, "ascii": ascii,
    "bytes": bytes, "bytearray": bytearray, "list": list, "tuple": tuple,
    "hex": hex, "oct": oct, "bin": bin, "int": int, "format": format,
    "reversed": lambda v: list(reversed(v)),
}

_METHODS = frozenset((
    "join", "decode", "encode", "replace", "upper", "lower", "strip", "lstrip",
    "rstrip", "format", "title", "capitalize", "swapcase", "zfill", "center",
    "ljust", "rjust", "split", "splitlines", "hex", "expandtabs", "translate",
))

_QUALIFIED = {
    ("base64", "b64decode"): _b64.b64decode,
    ("base64", "b32decode"): _b64.b32decode,
    ("base64", "b16decode"): _b64.b16decode,
    ("base64", "urlsafe_b64decode"): _b64.urlsafe_b64decode,
    ("base64", "a85decode"): _b64.a85decode,
    ("bytes", "fromhex"): bytes.fromhex,
    ("codecs", "decode"): _codecs.decode,
}


def _sized(value):
    if isinstance(value, (str, bytes, bytearray, list, tuple)) and len(value) > _FOLD_LIMIT:
        raise _NoFold()
    return value


def _fold(node: ast.AST, env: Dict[str, Any]):
    """The value this expression re-encodes from constants, or raise :class:`_NoFold`."""
    if isinstance(node, ast.Constant):
        return _sized(node.value)
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise _NoFold()
    if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
        items = [_fold(e, env) for e in node.elts]
        return _sized(items if isinstance(node, ast.List) else tuple(items))
    if isinstance(node, ast.JoinedStr):
        return _sized("".join(_fold(p, env) if isinstance(p, ast.FormattedValue)
                              else str(_fold(p, env)) for p in node.values))
    if isinstance(node, ast.FormattedValue):
        value = _fold(node.value, env)
        spec = "" if node.format_spec is None else str(_fold(node.format_spec, env))
        if node.conversion in (114, 115, 97):
            value = {114: repr, 115: str, 97: ascii}[node.conversion](value)
        return _sized(format(value, spec))
    if isinstance(node, ast.BinOp):
        return _sized(_fold_binop(node, env))
    if isinstance(node, ast.Subscript):
        return _sized(_fold(node.value, env)[_fold_index(node.slice, env)])
    if isinstance(node, (ast.GeneratorExp, ast.ListComp, ast.SetComp)):
        return _sized(_fold_comp(node, env))
    if isinstance(node, ast.Call):
        return _sized(_fold_call(node, env))
    raise _NoFold()


def _fold_binop(node: ast.BinOp, env: Dict[str, Any]):
    left, right = _fold(node.left, env), _fold(node.right, env)
    if isinstance(node.op, ast.Add) and isinstance(left, type(right)) \
            and isinstance(left, (str, bytes, list, tuple)):
        return left + right
    if isinstance(node.op, ast.Mult) and isinstance(left, (str, bytes, list, tuple)) \
            and isinstance(right, int) and 0 <= right <= _REPEAT_LIMIT:
        return left * right
    if isinstance(node.op, ast.Mod) and isinstance(left, (str, bytes)):
        try:
            return left % right
        except (TypeError, ValueError):
            raise _NoFold()
    raise _NoFold()


def _fold_index(node: ast.AST, env: Dict[str, Any]):
    if isinstance(node, ast.Slice):
        return slice(*[None if p is None else _fold(p, env)
                       for p in (node.lower, node.upper, node.step)])
    value = _fold(node, env)
    if not isinstance(value, int):
        raise _NoFold()
    return value


def _fold_comp(node, env: Dict[str, Any]):
    if len(node.generators) != 1:
        raise _NoFold()
    gen = node.generators[0]
    if gen.ifs or gen.is_async or not isinstance(gen.target, ast.Name):
        raise _NoFold()
    out = []
    for item in _fold(gen.iter, env):
        inner = dict(env)
        inner[gen.target.id] = item
        out.append(_fold(node.elt, inner))
        _sized(out)
    return out


def _fold_call(node: ast.Call, env: Dict[str, Any]):
    if any(isinstance(a, ast.Starred) for a in node.args) \
            or any(kw.arg is None for kw in node.keywords):
        raise _NoFold()
    args = [_fold(a, env) for a in node.args]
    kwargs = dict((kw.arg, _fold(kw.value, env)) for kw in node.keywords)
    fn = node.func
    if isinstance(fn, ast.Name):
        call = _TRANSCRIBERS.get(fn.id)
        if call is None:
            raise _NoFold()
    elif isinstance(fn, ast.Attribute):
        if isinstance(fn.value, ast.Name) and (fn.value.id, fn.attr) in _QUALIFIED:
            call = _QUALIFIED[(fn.value.id, fn.attr)]
        elif fn.attr in _METHODS:
            call = getattr(_fold(fn.value, env), fn.attr, None)
            if call is None:
                raise _NoFold()
        else:
            raise _NoFold()
    else:
        raise _NoFold()
    try:
        return call(*args, **kwargs)
    except _NoFold:
        raise
    except Exception:
        raise _NoFold()


def _folded_strings(tree: ast.AST) -> List[str]:
    """Every string this program can assemble without computing anything."""
    out: List[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.expr):
            continue
        try:
            value = _fold(node, {})
        except _NoFold:
            continue
        except RecursionError:
            continue
        if isinstance(value, (bytes, bytearray)):
            try:
                value = value.decode("utf-8")
            except UnicodeDecodeError:
                continue
        if isinstance(value, str) and value:
            out.append(value)
    return out


def _output_calls(tree: ast.AST) -> List[ast.Call]:
    found = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        fn = node.func
        if isinstance(fn, ast.Name) and fn.id == "print":
            found.append(node)
        elif isinstance(fn, ast.Attribute) and fn.attr in ("write", "writelines"):
            found.append(node)
    return sorted(found, key=lambda n: (getattr(n, "lineno", 0), getattr(n, "col_offset", 0)))


def _printed_constant(tree: ast.AST) -> Optional[str]:
    """Everything this program writes to stdout, when all of it is constant."""
    calls = _output_calls(tree)
    if not calls:
        return None
    out = []
    for node in calls:
        try:
            args = [_fold(a, {}) for a in node.args]
            kwargs = dict((kw.arg, _fold(kw.value, {})) for kw in node.keywords)
        except (_NoFold, RecursionError):
            return None
        if any(isinstance(a, ast.Starred) for a in node.args):
            return None
        if isinstance(node.func, ast.Name):
            if set(kwargs) - {"sep", "end"}:
                return None
            sep, end = kwargs.get("sep", " "), kwargs.get("end", "\n")
            if not isinstance(sep, str) or not isinstance(end, str):
                return None
            out.append(sep.join(str(a) for a in args) + end)
        else:
            if kwargs or len(args) != 1 or not isinstance(args[0], (str, list, tuple)):
                return None
            out.append(args[0] if isinstance(args[0], str) else "".join(args[0]))
    return "".join(out)

