from pipeline.lypning_source import classify_entry
from lypning.conformance import _SEED_CONTENT   # the repository's OWN seed bytes

REPO_SEED = _SEED_CONTENT['.json'].decode()      # '{"name": "seed", "items": [1, 2, 3]}'

# ---------- strategy C: shape inferred from the program's own AST -------------
LEAF = "seed"

class Shape:
    """A tiny structural lattice: keys/ index / leaf."""
    def __init__(self):
        self.keys = {}          # str -> Shape   (object)
        self.indexed = None     # Shape          (array)
        self.iterated = None    # Shape          (array, iterated)
    def key(self, k):
        return self.keys.setdefault(k, Shape())
    def idx(self):
        if self.indexed is None: self.indexed = Shape()
        return self.indexed
    def it(self):
        if self.iterated is None: self.iterated = Shape()
        return self.iterated
    def build(self, name="seed"):
        if self.keys:
            return {k: v.build(k) for k, v in sorted(self.keys.items())}
        child = self.indexed or self.iterated
        if child is not None:
            return [child.build(name), child.build(name)]
        return name

_ROOT_CALLS = ("load", "loads")

def _is_json_root(node):
    return (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
            and node.func.attr in _ROOT_CALLS
            and isinstance(node.func.value, ast.Name) and node.func.value.id == "json")

def infer(src):
    """A Shape for what the program subscripts out of the json root, or None."""
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return None
    root = Shape()
    names = set()          # variables bound to the json root
    aliases = {}           # var -> Shape  (loop variables etc.)

    def shape_of(node):
        """The Shape this expression denotes, or None if it is not rooted in json."""
        if _is_json_root(node):
            return root
        if isinstance(node, ast.Name):
            if node.id in names: return root
            return aliases.get(node.id)
        if isinstance(node, ast.Subscript):
            base = shape_of(node.value)
            if base is None: return None
            s = node.slice
            if isinstance(s, ast.Constant) and isinstance(s.value, str):
                return base.key(s.value)
            if isinstance(s, ast.Constant) and isinstance(s.value, int):
                return base.idx()
            return base.idx()
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            base = shape_of(node.func.value)
            if base is None: return None
            if node.func.attr == "get" and node.args and isinstance(node.args[0], ast.Constant) \
               and isinstance(node.args[0].value, str):
                return base.key(node.args[0].value)
            if node.func.attr in ("keys", "values", "items"):
                return None
        if isinstance(node, ast.BoolOp):          # d.get('x') or {}
            for v in node.values:
                s = shape_of(v)
                if s is not None: return s
        return None

    # two passes so `for c in d['cases']` sees `d` bound earlier or later
    for _ in range(3):
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign) and _is_json_root(node.value):
                for t in node.targets:
                    if isinstance(t, ast.Name): names.add(t.id)
            if isinstance(node, (ast.For, ast.comprehension)):
                it = node.iter
                s = shape_of(it)
                if s is not None:
                    tgt = node.target
                    if isinstance(tgt, ast.Name):
                        aliases[tgt.id] = s.it()
            for sub in ast.walk(node):
                shape_of(sub)
    if not (root.keys or root.indexed or root.iterated):
        return None
    return root

def shape_doc(src):
    s = infer(src)
    if s is None: return None
    return json.dumps(s.build())

# ---------- observation-driven repair ---------------------------------------
_KEYERR = re.compile(r"^KeyError: '([^']*)'", re.M)

def repair(src, argv, doc, rounds=6):
    """Bounded repair: add only the keys CPython's own KeyError names."""
    for _ in range(rounds):
        d = tempfile.mkdtemp(prefix='rep-')
        try:
            p = subprocess.run([sys.executable, '-c', src] + argv, input=doc,
                               capture_output=True, text=True, cwd=d, timeout=15)
        except subprocess.TimeoutExpired:
            return doc
        finally:
            pass
        if p.returncode == 0 and p.stdout.strip():
            return doc
        m = _KEYERR.search(p.stderr)
        if not m: return doc
        try: obj = json.loads(doc)
        except Exception: return doc
        if not isinstance(obj, dict): return doc
        obj[m.group(1)] = LEAF
        doc = json.dumps(obj)
    return doc

