LYP = engines.engine_path("lypning-l") or engines.engine_path("lypning")

def grade(src, stdin=None):
    """MATCH / UNSUPPORTED:<kind> / MISMATCH / ERROR, judged against CPython."""
    truth = sandbox.run_python(src, stdin=stdin, timeout_s=10)
    got = sandbox.run_python(src, stdin=stdin, timeout_s=10, interpreter=[LYP])
    if got.exit_code == 90:
        parsed = engines.parse_refusal(got.stderr)
        return "UNSUPPORTED", (parsed[1] if parsed else "?")
    if got.harness_error or truth.harness_error:
        return "ERROR", got.harness_error or truth.harness_error
    if (got.exit_code, got.stdout) == (truth.exit_code, truth.stdout):
        return "MATCH", ""
    return "MISMATCH", "exit %s/%s" % (truth.exit_code, got.exit_code)

